public class GRevokedUsageProbe {public static void main(String[]a){var live=new AtomicBoolean(true);var providerCalls=new AtomicInteger();var ledger=mock(AiModelUsageLedgerService.class);var raw=mock(ProjectAgentEventSink.class);var usage=new ProjectAgentUsageSink(raw,ledger,1L,"person","run");var spec=new ProjectAgentRunSpec(1L,2L,"t",3L,null,"synthetic",List.of(),List.of(),new KernelModelRequest("stub","stub","synthetic","https://synthetic.example"),null);var acl=new ProjectAgentRuntimeAccessSink(usage,spec,s->{if(!live.get())throw new IllegalStateException("synthetic revoked");});Model provider=new Model(){public String getModelName(){return "stub";}public Flux<ChatResponse> stream(List<Msg>m,List<ToolSchema>t,GenerateOptions o){providerCalls.incrementAndGet();live.set(false);return Flux.just(ChatResponse.builder().id("actual-response").usage(new ChatUsage(10,5,0)).content(List.of()).build());}};var metered=new ProjectAgentMeteredModel(provider,acl);boolean firstFailed=false;try{metered.stream(List.of(),null,null).blockLast();}catch(IllegalStateException expected){firstFailed=true;}boolean secondDenied=false;try{metered.stream(List.of(),null,null).blockLast();}catch(IllegalStateException expected){secondDenied=true;}System.out.println("BEGIN_ALLOWED_RETURN_REVOKED_FAILED="+firstFailed);System.out.println("ACTUAL_PROVIDER_CALLS="+providerCalls.get());System.out.println("ACTUAL_REPORTED_INPUT=10 OUTPUT=5");System.out.println("LEDGER_INVOCATIONS="+mockingDetails(ledger).getInvocations().size());System.out.println("NEW_MODEL_CALL_AFTER_REVOKE_DENIED="+secondDenied);if(!firstFailed||!secondDenied||providerCalls.get()!=1||!mockingDetails(ledger).getInvocations().isEmpty())throw new AssertionError("unexpected revocation contract");}}
